    # Deterministic vertex push: move the apex of the minimal triangle along
    # the perpendicular away from the opposite side, with a small line-search.
    def vertex_push(pts, rounds=4000):
        cur = project(np.array(pts, dtype=float))
        curA = min_area(cur)
        best, bestA = cur.copy(), curA
        for _ in range(rounds):
            p = cur[tri]
            s = 0.5 * ((p[:, 1, 0] - p[:, 0, 0]) * (p[:, 2, 1] - p[:, 0, 1])
                      - (p[:, 2, 0] - p[:, 0, 0]) * (p[:, 1, 1] - p[:, 0, 1]))
            k = int(np.argmin(np.abs(s)))
            i0, i1, i2 = tri[k]
            d = cur[i2] - cur[i1]
            L = np.hypot(*d)
            if L < 1e-14:
                break
            nrm = np.array([-d[1], d[0]]) / L
            if np.dot(nrm, cur[i0] - cur[i1]) * np.sign(s[k]) < 0:
                nrm = -nrm
            improved = False
            for step in (0.02, 0.01, 0.005, 0.002, 0.001, 0.0005):
                cand = cur.copy()
                cand[i0] = project(cand[i0][None, :] + step * nrm[None, :])[0]
                mA = min_area(cand)
                if mA > curA + 1e-14:
                    cur, curA = cand, mA
                    if mA > bestA:
                        best, bestA = cand.copy(), mA
                    improved = True
                    break
            if not improved:
                break
        return best, bestA

